import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/db";
import { hashWebhookSecret } from "@/lib/webhooks/secret";
import { resolveVenueId } from "@/lib/venues/resolve";

/**
 * Inbound webhook for external integrations (calendar systems, HR tools).
 *
 * Auth: `x-webhook-secret` is a PER-BUSINESS secret, generated by an admin at
 * POST /api/business/webhook-secret. The business is resolved FROM the secret
 * and every operation is scoped to it — a caller can never act on another
 * tenant, whatever ids it puts in the body.
 *
 * (Previously one global WEBHOOK_SECRET let the holder create bookings for any
 * businessId and cancel/approve any reservation or time-off request by id.)
 */

const NOT_FOUND = { error: "Not found" };

async function businessFromSecret(req: NextRequest): Promise<string | null> {
  const secret = req.headers.get("x-webhook-secret");
  if (!secret || secret.length < 20 || secret.length > 200) return null;
  const business = await prisma.business.findUnique({
    where: { webhookSecretHash: hashWebhookSecret(secret) },
    select: { id: true },
  });
  return business?.id ?? null;
}

function str(v: unknown, max: number): string | null {
  if (typeof v !== "string") return null;
  const t = v.trim();
  return t ? t.slice(0, max) : null;
}

export async function POST(req: NextRequest) {
  const businessId = await businessFromSecret(req);
  if (!businessId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  let body: any;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }
  const event = body?.event;
  const data = body?.data ?? {};

  switch (event) {
    case "booking.create": {
      // Any businessId in the payload is ignored; the secret decides.
      const date = new Date(data.date);
      if (!data.date || isNaN(date.getTime())) {
        return NextResponse.json({ error: "data.date is required (ISO date)" }, { status: 400 });
      }
      const partySize = Number.parseInt(data.partySize ?? 1, 10);
      if (!Number.isFinite(partySize) || partySize < 1 || partySize > 500) {
        return NextResponse.json({ error: "data.partySize must be 1-500" }, { status: 400 });
      }

      let tableId: string | null = null;
      if (data.tableId) {
        const table = await prisma.table.findFirst({
          where: { id: String(data.tableId), businessId },
          select: { id: true },
        });
        if (!table) return NextResponse.json({ error: "Unknown tableId" }, { status: 400 });
        tableId = table.id;
      }

      const reservation = await prisma.reservation.create({
        data: {
          businessId,
          venueId: await resolveVenueId(businessId, data.venueId ? String(data.venueId) : null),
          customerName: str(data.customerName, 100) ?? "Webhook Guest",
          customerPhone: str(data.customerPhone, 30),
          customerEmail: str(data.customerEmail, 200),
          partySize,
          date,
          time: str(data.time, 10) ?? "19:00",
          tableId,
          createdByName: "Webhook",
        },
      });
      return NextResponse.json({ success: true, reservation });
    }

    case "booking.cancel": {
      const result = await prisma.reservation.updateMany({
        where: { id: String(data.reservationId ?? ""), businessId },
        data: { status: "cancelled" },
      });
      if (result.count === 0) return NextResponse.json(NOT_FOUND, { status: 404 });
      return NextResponse.json({ success: true });
    }

    case "timeoff.approve": {
      // TimeOffRequest has no businessId column — scope through the employee.
      const result = await prisma.timeOffRequest.updateMany({
        where: { id: String(data.requestId ?? ""), employee: { businessId } },
        data: { status: "APPROVED" },
      });
      if (result.count === 0) return NextResponse.json(NOT_FOUND, { status: 404 });
      return NextResponse.json({ success: true });
    }

    default:
      return NextResponse.json({ error: `Unknown event: ${event}` }, { status: 400 });
  }
}

export async function GET() {
  return NextResponse.json({
    status: "ok",
    auth: "x-webhook-secret header (per-business; generate in Settings → General)",
    supportedEvents: ["booking.create", "booking.cancel", "timeoff.approve"],
  });
}
